import{z as B,x as i,o as E,c as l,q as e,j as r,D as s,d as t,s as o,S as A}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"zswap","description":"","frontmatter":{"title":"zswap","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/zswap.md","filePath":"cs/zswap.md","lastUpdated":1791413859000}'),n={name:"cs/zswap.md"};function c(d,a,m,w,_,z){const p=i("Mermaid");return E(),l("div",null,[a[2]||(a[2]=e('<h1 id="zswap" tabindex="-1">zswap <a class="header-anchor" href="#zswap" aria-label="Permalink to &quot;zswap&quot;">​</a></h1><div class="epigraph"><p>zswap 在页被换出到盘之前先压缩进内存池：命中则解压回，池满再真正写交换设备。</p><footer>—— 据 Linux zswap 文档；zbud/zsmalloc 分配器说明</footer></div><p><a href="/cs/ksm">KSM</a> 去重仍在「未换出」的世界。内存仍紧则走交换。<a href="/cs/writeback">writeback</a> 对文件页；匿名页走 swap。缺口是 <strong>zswap</strong>：用 CPU 压缩换磁盘 I/O。不是 zram 整盘当 swap 的同一实例，但亲戚。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>SSD 再快，压缩 4K 到 1K 并留在 RAM 往往更低延迟。zswap：frontswap 钩，换出时压缩，键是 swap 槽。缺口：压缩算法、池大小、拒绝（incompressible）；与 <a href="/cs/memcg">memcg</a> 的交换会计；和 zram 的差别——zram 是块设备，zswap 是交换路径缓存。本课不把每个 compressor 基准写成附录。</p><p><span class="marginnote">数字实例：一个 4 KB 匿名页若压到 1 KB，内存池同容量能装 4 倍的页；换入时省掉一次 SSD 读（几十微秒起），多付的是一次解压（微秒级）。但若页里是已压缩的照片，压完还是 4 KB，这轮尝试纯属白烧 CPU。</span></p><p><span class="marginnote">同页再次换入命中 zswap 则不读盘。写回：池满按 LRU 把压缩页解开或直接写 swap（视实现）。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>pageout</code>：尝试 zswap store，成功则不立即发 bio。<code>pagein</code>：load 解压。对照 <a href="/cs/bcache">bcache</a>：一个缓存块设备，一个缓存交换页。对照 THP：大页通常先拆再进 zswap。</p>',9)),(E(),r(A,null,{default:s(()=>[o(p,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20RECLAIM%5B%22%E5%9B%9E%E6%94%B6%E5%8C%BF%E5%90%8D%E9%A1%B5%22%5D%20--%3E%20ZS%5B%22zswap%20%E5%8E%8B%E7%BC%A9%22%5D%0A%20%20ZS%20--%3E%7C%22%E6%B1%A0%E8%BF%98%E6%9C%89%E7%A9%BA%22%7C%20MEM%5B%22%E5%8E%8B%E7%BC%A9%E6%B1%A0%22%5D%0A%20%20ZS%20--%3E%7C%22%E6%BB%A1%E6%88%96%E4%B8%8D%E5%80%BC%E5%BE%97%22%7C%20SW%5B%22%E4%BA%A4%E6%8D%A2%E8%AE%BE%E5%A4%87%22%5D%0A%20%20FAULT%5B%22%E7%BC%BA%E9%A1%B5%22%5D%20--%3E%20MEM%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>zswap 把交换从「必定盘 I/O」变成「先 CPU 再盘」，改善超售。它消耗 CPU 与不可移动的压缩池，可能妨碍 <a href="/cs/page-migration-compaction">compaction</a>。不要写成云内存产品。与 <a href="/cs/direct-io">O_DIRECT</a> 无关。</p><p><span class="marginnote">直觉类比：zswap 是书桌旁的一个压缩收纳箱——书架（RAM）放不下的书先压缩塞箱；找书时从箱里取（解压，快）；箱子满了才把一部分真送去地下库（swap 盘，慢）。代价是每次收纳和取出都要动手打包，箱子本身还占桌面。</span></p><p><span class="marginnote">常见误区：初学者容易把 zswap 与 zram 混为一谈。zram 是凭空造一块压缩块设备当 swap 用；zswap 不造设备，它挂在真 swap 路径上当&quot;第一道缓存&quot;。两者同时开会把同一页压两遍，通常二选一。</span></p>',4)),(E(),r(A,null,{default:s(()=>[o(p,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E7%BC%BA%E9%A1%B5%EF%BC%9A%E8%BF%9B%E7%A8%8B%E8%A6%81%E8%BF%99%E9%A1%B5%22%5D%20--%3E%20Q%7B%22%E9%A1%B5%E5%9C%A8%20zswap%20%E6%B1%A0%E9%87%8C%E5%90%97%22%7D%0A%20%20Q%20--%3E%20HIT%5B%22%E5%9C%A8%EF%BC%9A%E8%A7%A3%E5%8E%8B%E5%9B%9E%20RAM%EF%BC%8C%E4%B8%8D%E7%A2%B0%E7%9B%98%22%5D%0A%20%20Q%20--%3E%20MISS%5B%22%E4%B8%8D%E5%9C%A8%EF%BC%9A%E8%AF%BB%20swap%20%E8%AE%BE%E5%A4%87%22%5D%0A%20%20HIT%20--%3E%20FAST%5B%22%E5%BE%AE%E7%A7%92%E7%BA%A7%E5%BB%B6%E8%BF%9F%22%5D%0A%20%20MISS%20--%3E%20SLOW%5B%22%E6%AF%AB%E7%A7%92%E7%BA%A7%20I%2FO%22%5D%0A%20%20POOL%5B%22%E6%B1%A0%E6%BB%A1%E8%A7%A6%E5%8F%91%E5%86%99%E5%9B%9E%22%5D%20--%3E%20EV%5B%22%E6%8C%89%20LRU%20%E9%80%89%E5%8E%8B%E7%BC%A9%E9%A1%B5%22%5D%0A%20%20EV%20--%3E%20SW%5B%22%E6%89%B9%E9%87%8F%E5%86%99%E5%9B%9E%E4%BA%A4%E6%8D%A2%E8%AE%BE%E5%A4%87%22%5D%0A%20%20SW%20--%3E%20ROOM%5B%22%E8%85%BE%E5%87%BA%E6%B1%A0%E7%A9%BA%E9%97%B4%22%5D%0A"})]),fallback:s(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e('<p>安全：压缩数据仍是明文，在 RAM 里。</p><p>实现上：不可压缩页浪费一次压缩尝试。zsmalloc 的对象不可直接 DMA，换入要先解压到正规页。与 zram 同时用会双重压缩，通常选一个。 读法上只引用<a href="/cs/ksm">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「内存进阶 / 回收、迁移与加固」课序里，对象是 <strong>zswap</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 zswap 的 writeback 策略全部 sysfs。不保证实时负载该开。下一课把页放到哪一节点：NUMA 内存策略。</p><p>版本字段会变，课序钉的是机制对象「zswap」，不是某一主线内核的结构体名。 后课默认：换出路径可压缩缓存。进程如何绑定节点与交错，下一课 mempolicy。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>zswap 压缩即将换出的匿名页，减少盘 I/O。</li><li>池与 CPU 是税；zram 是另一形态。</li><li>NUMA 策略是下一课。</li><li>出处：Linux zswap；frontswap；Gorman 交换背景。</li></ul>',9))])}const u=B(n,[["render",c]]);export{C as __pageData,u as default};
